    input = sys.stdin.read().split('\n')
    index = 0
    t = int(input[index])
    index += 1
    results = []

    while t > 0:
        n, m = map(int, input[index].split())
        index += 1
        degrees = [0] * (n + 1)
        graph = defaultdict(list)

        for _ in range(m):
            a, b = map(int, input[index].split())
            graph[a].append(b)
            graph[b].append(a)
            degrees[a] += 1
            degrees[b] += 1
            index += 1

        if n == 1:
            results.append("No")
            continue

        if m == 0:
            results.append("No")
            continue

        # Check if we can find a valid set of vertices to remove
        def can_steal(vertices):
            new_degrees = degrees[:]
            for v in vertices:
                for neighbor in graph[v]:
                    new_degrees[neighbor] -= 1
            for d in new_degrees[1:]:
                if d % 3 != 0:
                    return False
            return True

        found = False
        for i in range(1, n):
            if can_steal([i]):
                found = True
                results.append(f"Yes\n1\n{i}")
                break

        if not found:
            for i in range(1, n):
                for j in range(i + 1, n + 1):
                    if can_steal([i, j]):
                        found = True
                        results.append(f"Yes\n2\n{i} {j}")
                        break
                if found:
                    break

        if not found:
            for i in range(1, 4):
                for comb in combinations(range(1, n + 1), i):
                    if can_steal(comb):
                        found = True
                        results.append(f"Yes\n{i}\n{' '.join(map(str, comb))}")
                        break
                if found:
                    break

        if not found and n >= 3:
            for i in range(1, n - 1):
                for j in range(i + 1, n):
                    for k in range(j + 1, n + 1):
                        if can_steal([i, j, k]):
                            found = True
                            results.append(f"Yes\n3\n{i} {j} {k}")
                            break
                    if found:
                        break
                if found:
                    break

        if not found:
                results.append("No")

        t -= 1

    for result in results:
        print(result)

if __name__ == "__main__":
    main()
